mapper.select:
select c.*, u.nickname as boundMemberName, u.phone as boundMemberMobile, (select group_concat(s.storeName order by r.store_id) from pt_coach_store_rel r left join store_address sa on sa.storeAddrId = r.store_id left join store s on s.storeId = sa.storeId where r.coach_id = c.id) as storeNames, (select group_concat(r.store_id order by r.store_id) from pt_coach_store_rel r where r.coach_id = c.id) as storeIdCsv, (select count(1) from pt_coach_schedule sc where sc.coach_id = c.id) as scheduleCount from pt_coach c left join user_info u on u.userId = c.user_id and u.isDel = 0
c.deleted = 0
AND c.coach_name LIKE concat('%',#{coachName},'%')
AND c.mobile LIKE concat('%',#{mobile},'%')
AND c.status = #{status}
AND c.coach_type = #{coachType}
AND c.coach_level = #{coachLevel}
AND EXISTS (select 1 from pt_coach_store_rel r where r.coach_id = c.id and r.store_id = #{storeId})
AND ( (#{hasSchedule} = 1 AND EXISTS (select 1 from pt_coach_schedule sc where sc.coach_id = c.id)) OR (#{hasSchedule} = 0 AND NOT EXISTS (select 1 from pt_coach_schedule sc where sc.coach_id = c.id)) )
AND c.created_at >= #{beginTime}
AND c.created_at < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
AND c.id IN (select coach_id from pt_coach_store_rel where store_id in (${storeIds}))
order by ${sidx} ${order}
order by c.sort_no desc, c.id desc
limit #{offset}, #{limit}

select count(*) from pt_coach c
c.deleted = 0
AND c.coach_name LIKE concat('%',#{coachName},'%')
AND c.mobile LIKE concat('%',#{mobile},'%')
AND c.status = #{status}
AND c.coach_type = #{coachType}
AND c.coach_level = #{coachLevel}
AND EXISTS (select 1 from pt_coach_store_rel r where r.coach_id = c.id and r.store_id = #{storeId})
AND ( (#{hasSchedule} = 1 AND EXISTS (select 1 from pt_coach_schedule sc where sc.coach_id = c.id)) OR (#{hasSchedule} = 0 AND NOT EXISTS (select 1 from pt_coach_schedule sc where sc.coach_id = c.id)) )
AND c.created_at >= #{beginTime}
AND c.created_at < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
AND c.id IN (select coach_id from pt_coach_store_rel where store_id in (${storeIds}))

select count(*) from pt_coach
where deleted = 0 and mobile = #{mobile}
AND id <> #{excludeId}

select count(*) from pt_coach
where deleted = 0 and user_id = #{userId}
AND id <> #{excludeId}
